    DECLARE @V_CURR_PRE_TO_YYYYMMDD     NVARCHAR(8)         = '';
    DECLARE @V_CURR_POST_FROM_YYYYMMDD  NVARCHAR(8)         = '';
    DECLARE @V_CURR_POST_TO_YYYYMMDD    NVARCHAR(8)         = '';
    DECLARE @V_CURR_FG_SEQ_P            BIGINT;
    DECLARE @V_CURR_FG_SEQ_R            BIGINT;

